# Mirror notifications/emails from the hand-written section (kept in sync with notify())
import copy
for lang_idx, lang in enumerate(["ar", "en"]):
    def pick(x):
        if isinstance(x, tuple): return x[lang_idx]
        return {k: pick(v) for k, v in x.items()}
    out = pick(M)
    out["dashboard"]["challenge_status"] = out["enums"]["status"]
    old = json.load(open(f"messages/{lang}.json"))
    out["notifications"] = {**old["notifications"], **out["notifications"]}
    out["emails"] = old["emails"]
    json.dump(out, open(f"messages/{lang}.json", "w"), ensure_ascii=False, indent=2)
print("ok")
